import os
import re
import hashlib
import hmac
from pathlib import PurePosixPath

# Configuration
UPLOAD_ROOT = os.environ.get('UPLOAD_ROOT', '/var/uploads')

_raw_hmac_key = os.environ.get('HMAC_KEY', '')
if not _raw_hmac_key or len(_raw_hmac_key) < 32:
    raise RuntimeError(
        "HMAC_KEY environment variable must be set to a strong secret "
        "(at least 32 characters). Refusing to start with a missing or weak key."
    )
HMAC_KEY = _raw_hmac_key.encode()

ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc'}


class InputValidator:
    """Validates user-supplied filenames and paths."""

    # Only allow alphanumeric, underscore, hyphen, and dot
    SAFE_FILENAME_RE = re.compile(r'\A[a-zA-Z0-9_\-\.]+\Z')

    # Only allow alphanumeric and underscore for directory names
    SAFE_DIRNAME_RE = re.compile(r'\A[a-zA-Z0-9_]+\Z')

    @classmethod
    def validate_filename(cls, filename: str) -> bool:
        """Check filename contains only safe characters."""
        if not filename or len(filename) > 255:
            return False
        if '..' in filename:
            return False
        return cls.SAFE_FILENAME_RE.match(filename) is not None

    @classmethod
    def validate_dirname(cls, dirname: str) -> bool:
        """Check directory name contains only safe characters."""
        if not dirname or len(dirname) > 64:
            return False
        if '..' in dirname:
            return False
        return cls.SAFE_DIRNAME_RE.match(dirname) is not None


class SecureFileStore:
    """Handles file storage with integrity verification."""

    def __init__(self, root_path: str, hmac_key: bytes):
        self._root = os.path.realpath(root_path)
        self._hmac_key = hmac_key

    def _compute_integrity(self, data: bytes) -> str:
        """Compute HMAC-SHA256 for data integrity."""
        return hmac.new(self._hmac_key, data, hashlib.sha256).hexdigest()

    def _verify_integrity(self, data: bytes, signature: str) -> bool:
        """Verify data integrity using constant-time comparison."""
        expected = self._compute_integrity(data)
        return hmac.compare_digest(expected, signature)

    def _resolve_path(self, user_dir: str, filename: str) -> str:
        """Resolve the full path for a file within user's directory."""
        # Validate components
        if not InputValidator.validate_dirname(user_dir):
            raise ValueError(f"Invalid directory name: {user_dir!r}")
        if not InputValidator.validate_filename(filename):
            raise ValueError(f"Invalid filename: {filename!r}")

        # Check extension
        ext = os.path.splitext(filename)[1].lower()
        if ext not in ALLOWED_EXTENSIONS:
            raise ValueError(f"Extension not allowed: {ext}")

        # Build path
        full_path = os.path.join(self._root, user_dir, filename)

        # Verify resolved path is under root
        resolved = os.path.realpath(full_path)
        if not resolved.startswith(self._root + os.sep):
            raise ValueError("Path traversal detected")

        return resolved

    def store_file(self, user_dir: str, filename: str, data: bytes) -> dict:
        """Store a file with integrity metadata."""
        path = self._resolve_path(user_dir, filename)

        # Ensure directory exists
        os.makedirs(os.path.dirname(path), exist_ok=True)

        # Write file
        with open(path, 'wb') as f:
            f.write(data)

        # Compute and store integrity
        integrity = self._compute_integrity(data)
        meta_path = path + '.meta'
        with open(meta_path, 'w') as f:
            f.write(integrity)

        return {'path': path, 'integrity': integrity, 'size': len(data)}

    def read_file(self, user_dir: str, filename: str) -> bytes:
        """Read a file after verifying integrity."""
        path = self._resolve_path(user_dir, filename)

        if not os.path.exists(path):
            raise FileNotFoundError(f"File not found: {filename}")

        with open(path, 'rb') as f:
            data = f.read()

        # Verify integrity
        meta_path = path + '.meta'
        if os.path.exists(meta_path):
            with open(meta_path, 'r') as f:
                stored_sig = f.read().strip()
            if not self._verify_integrity(data, stored_sig):
                raise ValueError("File integrity check failed")

        return data

    def list_files(self, user_dir: str) -> list:
        """List files in a user's directory."""
        if not InputValidator.validate_dirname(user_dir):
            raise ValueError(f"Invalid directory name: {user_dir!r}")

        dir_path = os.path.join(self._root, user_dir)
        resolved_dir = os.path.realpath(dir_path)

        if not resolved_dir.startswith(self._root + os.sep):
            raise ValueError("Path traversal detected")

        if not os.path.isdir(resolved_dir):
            return []

        return [
            f for f in os.listdir(resolved_dir)
            if not f.endswith('.meta') and os.path.isfile(os.path.join(resolved_dir, f))
        ]


# Application entry point
store = SecureFileStore(UPLOAD_ROOT, HMAC_KEY)
